  --nys-button-background-color--hover: var(--nys-color-danger-strong);
  --nys-button-background-color--active: var(--nys-color-danger-strong);
}

/* Pretend this is the next release of @nysds/styles. */
:root {
  --nys-font-family-ui: var(--nys-font-family-serif);
  --nys-radius-xl: var(--nys-radius-round);
}

.stat { display: grid; margin: 0; }
.stat strong { display: block; line-height: var(--nys-font-lineheight-h2); }

/* The card is the system's. What you slot into it is yours. */

/* What the guidance asks for */
.stat--tokens {
  gap: var(--nys-space-100);
  padding: var(--nys-space-300);
  border-left: var(--nys-border-width-md) solid var(--nys-color-theme);
  background: var(--nys-color-theme-faint);
  font-family: var(--nys-font-family-ui);
  color: var(--nys-color-text);
}
.stat--tokens strong {
  font-size: var(--nys-font-size-h2);
  font-weight: var(--nys-font-weight-bold);
}
.stat--tokens span {
  font-size: var(--nys-font-size-body-sm);
  color: var(--nys-color-text-weak);
}

/* What the guidance can't prevent */
.stat--hardcoded {
  gap: 0.5rem;
  padding: 1.5rem;
  border-left: 2px solid #154973;
  background: #f7fafd;
  font-family: "Proxima Nova", Arial, sans-serif;
  color: #1b1b1b;
}
.stat--hardcoded strong {
  font-size: 2rem;
  font-weight: 700;
}
.stat--hardcoded span {
  font-size: 0.875rem;
  color: #4a4d4f;
}

/* Uncomment to "release" a system change:
:root {
  --nys-font-family-ui: var(--nys-font-family-serif);
  --nys-color-theme: var(--nys-color-danger);
}
*/

/* Uses tokens: follows whatever theme the page gets. */
.tokens .banner {
  background: var(--nys-color-theme);
  color: var(--nys-color-text-reverse);
}
.tokens .cta {
  --nys-button-background-color: var(--nys-color-theme-strong);
  --nys-button-background-color--hover: var(--nys-color-theme-stronger);
  --nys-button-background-color--active: var(--nys-color-theme-stronger);
}

/* Hard-coded on purpose: the same colors, copied as hex values.
   No theme can reach them. */
.hardcoded .banner {
  background: #154973;
  color: #ffffff;
}
.hardcoded .cta {
  --nys-button-background-color: #0e324f;
  --nys-button-background-color--hover: #081b2b;
  --nys-button-background-color--active: #081b2b;
}

/* The banner and the darker "Renew now" are the team's customizations.
   The header, the cards, and "Check status" are the system's, untouched. */
.banner {
  margin: 0;
  padding: var(--nys-space-200) var(--nys-space-300);
  border-radius: var(--nys-radius-md);
}

/* A tighter gap than the deck's default keeps the buttons clear of the code drawer. */
body {
  gap: var(--nys-space-200);
}

presets.js:
// Apply the theme the way an app does: one class on the root element.
const themes = ['admin', 'business', 'environment', 'health', 'local', 'safety', 'transportation'];

document.querySelector('#agency-theme').addEventListener('nys-change', (event) => {
  const root = document.documentElement;
  root.classList.remove(...themes.map((id) => `nys-theme-${id}`));
  if (themes.includes(event.detail.value)) {
    root.classList.add(`nys-theme-${event.detail.value}`);
  }
});

